const ITEM_MAP = new Map<string, RealWorldArtItem>(
  REALWORLD_CATALOG.map((item) => [item.id, item])
);

const RECENT_STORAGE_KEY = "wb.thucTe.recent";
const MAX_RECENT = 6;

/**
 * Retrieves a real-world SVG catalog item by id, falling back to "pole" when unknown.
 */
export function getRealWorldItem(id: string): RealWorldArtItem {
  return ITEM_MAP.get(id) ?? ITEM_MAP.get("pole") ?? REALWORLD_CATALOG[0];
}

/**
 * Strips Vietnamese diacritics and normalizes text for accent-insensitive search.
 */
export function normalizeVietnamese(input: string): string {
  return input
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/đ/g, "d")
    .replace(/Đ/g, "D")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

/**
 * Searches the 100-item catalog by Vietnamese name, keywords, or id (accent-insensitive).
 */
export function searchRealWorldCatalog(
  query: string,
  category?: RealWorldCategory | "all"
): RealWorldArtItem[] {
  const pool =
    category && category !== "all"
      ? REALWORLD_CATALOG.filter((item) => item.group === category)
      : [...REALWORLD_CATALOG];

  const q = normalizeVietnamese(query);
  if (!q) return pool;

  const words = q.split(/\s+/).filter(Boolean);
  return pool.filter((item) => {
    const haystack = normalizeVietnamese(
      [item.name, item.id, item.group, ...item.keywords].join(" ")
    );
    return words.every((w) => haystack.includes(w));
  });
}

/**
 * Reads recently selected real-world item IDs from localStorage["wb.thucTe.recent"].
 */
export function getRecentRealWorldIds(): string[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(RECENT_STORAGE_KEY);
    if (!raw) return [];
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter((id): id is string => typeof id === "string" && ITEM_MAP.has(id))
      .slice(0, MAX_RECENT);
  } catch {
    return [];
  }
}

/**
 * Records a selected real-world item ID at the front of localStorage["wb.thucTe.recent"].
 */
export function recordRecentRealWorldId(id: string): string[] {
  if (!ITEM_MAP.has(id)) return getRecentRealWorldIds();
  const next = [id, ...getRecentRealWorldIds().filter((x) => x !== id)].slice(
    0,
    MAX_RECENT
  );
  if (typeof window !== "undefined") {
    try {
      window.localStorage.setItem(RECENT_STORAGE_KEY, JSON.stringify(next));
    } catch {
      // Ignore storage quota errors
    }
  }
  return next;
}
